# Extract exact original manuscript inputs; replay the author's R gam helper for six Fig2f genes.
a<-commandArgs(TRUE);P<-normalizePath(a[1]);run_id<-if(length(a)>1)a[2]else'run1';W<-file.path(P,'work/2026-10-28-batch-six/single-cell');.libPaths(c(file.path(W,'Rlib'),file.path(P,'work/2026-10-11-next-complex-training/ohca/R-library'),.libPaths()));suppressPackageStartupMessages({library(rhdf5);library(gam)})
D<-file.path(W,'data/raw/human_cd34_bm_rep1.h5ad');O<-file.path(W,'results/plot_data');obs<-h5read(D,'obs');var<-as.character(h5read(D,'var')$index);obsm<-h5read(D,'obsm',compoundAsDataFrame=FALSE);branches<-as.character(h5read(D,'uns/palantir_branch_probs_cell_types'));genes<-c('CD34','CD79B','GATA1','IRF8','MPO','ITGA2B');labels<-c('CD34','CD79B','GATA1','IRF8','MPO','CD41');stopifnot(nrow(obs)==5780L,identical(dim(obsm$tsne),c(2L,5780L)),identical(dim(obsm$palantir_branch_probs),c(6L,5780L)),!anyDuplicated(obs$index),all(genes%in%var))
cells<-data.frame(cell_id=as.character(obs$index),cluster_id=as.integer(obs$clusters),tsne_x=obsm$tsne[1,],tsne_y=obsm$tsne[2,],pseudotime=obs$palantir_pseudotime,differentiation_potential=obs$palantir_diff_potential,check.names=FALSE)
weights<-t(obsm$palantir_branch_probs);colnames(weights)<-branches;stopifnot(all(is.finite(as.matrix(cells[,-1]))),all(weights>=0),all(weights<=1),all(rowSums(weights)>.97),all(rowSums(weights)<=1+1e-10))
for(b in branches)cells[[paste0('prob_',b)]]<-weights[,b]
raw_expr<-t(obsm$MAGIC_imputed_data[match(genes,var),,drop=FALSE]);colnames(raw_expr)<-genes;norm_expr<-apply(raw_expr,2,function(y)(y-min(y))/(max(y)-min(y)));stopifnot(all(is.finite(norm_expr)),min(norm_expr)==0,max(norm_expr)==1)
write.csv(cells,file.path(O,'cells.csv'),row.names=FALSE);write.csv(data.frame(cell_id=cells$cell_id,raw_expr,check.names=FALSE),file.path(O,'marker_magic_source.csv'),row.names=FALSE);write.csv(data.frame(cell_id=cells$cell_id,norm_expr,check.names=FALSE),file.path(O,'marker_minmax01.csv'),row.names=FALSE)
map<-data.frame(source_gene_id=genes,figure_label=labels,minimum=apply(raw_expr,2,min),maximum=apply(raw_expr,2,max),normalization='(MAGIC-min)/(max-min),all5780cells per gene');write.csv(map,file.path(O,'marker_mapping.csv'),row.names=FALSE)
# Exact v0.2.6 _gam_fit_predict equations: R package gam, y~s(x), positive-weight support,
# 500 bins ending at max pseudotime with branch probability>0.7; residual sigma/2 band, not95%CI.
source_gam<-function(x,y,weights,pred_x){use<-weights>0;dat<-data.frame(x=x[use],y=y[use]);m<-gam::gam(y~s(x),data=dat,weights=weights[use]);fit<-as.numeric(predict(m,newdata=data.frame(x=pred_x)));training<-as.numeric(predict(m,newdata=dat));n<-sum(use);sigma<-sqrt(sum((y[use]-training)^2)/(n-2));std<-sqrt(1+1/n+(pred_x-mean(x))^2/sum((x-mean(x))^2))*sigma/2;list(fit=fit,std=std,n=n,sigma=sigma,coef=coef(m),edf=sum(m$nl.df)+m$rank,model=m)}
trends<-list();audits<-list();models<-list();k<-0L
for(b in branches){bins<-seq(0,max(cells$pseudotime[weights[,b]>.7]),length.out=500);for(i in seq_along(genes)){g<-genes[i];v<-source_gam(cells$pseudotime,norm_expr[,g],weights[,b],bins);k<-k+1L;trends[[k]]<-data.frame(branch=b,gene_id=g,gene_label=labels[i],pseudotime=bins,fit=v$fit,source_std=v$std,lower=v$fit-v$std,upper=v$fit+v$std);audits[[k]]<-data.frame(branch=b,gene_id=g,positive_weight_cells=v$n,weight_sum=sum(weights[,b]),terminal_pseudotime=max(bins),prediction_points=length(bins),sigma=v$sigma,edf=v$edf,coefficient_sha256=digest::digest(v$coef,algo='sha256'));models[[paste(b,g,sep=':')]]<-v$model}}
d<-do.call(rbind,trends);audit<-do.call(rbind,audits);stopifnot(nrow(d)==18000L,all(is.finite(d$fit)),all(is.finite(d$source_std)),all(d$source_std>0));write.csv(d,file.path(O,'gam_trends.csv'),row.names=FALSE);selected<-d[d$branch!='Mega'|d$gene_id=='ITGA2B',];stopifnot(nrow(selected)==15500L);write.csv(selected,file.path(O,'publication_selected_trends.csv'),row.names=FALSE);write.csv(data.frame(gene_id=genes,gene_label=labels,lineages_shown=c(rep('CLP;Ery;Mono;cDC;pDC',5),'CLP;Ery;Mega;Mono;cDC;pDC')),file.path(O,'publication_lineage_mapping.csv'),row.names=FALSE);write.csv(audit,file.path(O,'gam_model_audit.csv'),row.names=FALSE);saveRDS(models,file.path(O,paste0('gam_models_',run_id,'.rds')))
raw_h5_hash<-digest::digest(file=D,algo='sha256');qc<-list(status='PASS_SOURCE_FIELDS_AND_CURRENT_DESCRIPTIVE_GAM',input_sha256=raw_h5_hash,cells=nrow(cells),source_genes=length(var),branches=branches,model_count=36,prediction_rows=nrow(d),displayed_prediction_rows=nrow(selected),displayed_curves=31,publication_subset='Mega appears only inCD41/ITGA2B inoriginalFig2f;all36fittedmodelsretained',branch_probability_rowsum_range=range(rowSums(weights)),branch_probability_source_threshold='Author PResults zeros probabilities<0.01 without renormalizing; preserve original row sums0.973075..1',source_identifiers_preserved=TRUE,embedding_recomputed=FALSE,normalization=map,missing=0,stats_scope='Descriptive replay of author gam smoothing and exact residual sigma/2 band; no hypothesis test,confidence-level or independent cell replicate claim.',fit_range=range(d$fit),band_range=range(c(d$lower,d$upper)),software=list(R=R.version.string,gam=as.character(packageVersion('gam')),rhdf5=as.character(packageVersion('rhdf5'))));jsonlite::write_json(qc,file.path(W,'evidence',paste0('input-qc-',run_id,'.json')),pretty=TRUE,auto_unbox=TRUE,digits=NA);jsonlite::write_json(qc,file.path(W,'evidence/input-qc.json'),pretty=TRUE,auto_unbox=TRUE,digits=NA);capture.output(sessionInfo(),file=file.path(W,'evidence/data-sessionInfo.txt'));cat('PREPARED',nrow(cells),'cells',nrow(d),'GAMprediction rows\n');print(range(d$fit));print(range(c(d$lower,d$upper)))
